import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>تحويل JPG إلى PNG يبدو كتحسين. PNG يبدو أفضل، ودون فقدان يبدو أفضل، والملف الأكبر يبدو أجود.</p>\n<p>تحويل JPG إلى PNG لا يحسّن الصورة أبدًا. يحفظ JPG كما هو، بعيوبه، ويضاعف حجم الملف فقط.</p>\n<p>يشرح هذا الدليل متى يستحق هذا التغيير، ومتى يكون مضيعة للمساحة.</p>\n<h2 id=\"what-happens-in-conversion\">ماذا يحدث عند تحويل JPG إلى PNG؟</h2>\n<p>ماذا يحدث عند تحويل JPG إلى PNG؟ الأداة تفك ضغط JPG إلى بكسلات، ثم تعيد ترميزها كـPNG دون فقدان. الصورة نفسها لا تتغير.</p>\n<p>النتيجة ملف أكبر بالصورة نفسها. لا تفاصيل جديدة ولا حدة إضافية، فقط تنسيق مختلف للبيانات نفسها.</p>\n<h2 id=\"why-files-get-bigger\">لماذا تكبر ملفات PNG كثيرًا؟</h2>\n<p>لماذا تكبر ملفات PNG كثيرًا؟ لأن PNG ضغط دون فقدان: يحفظ كل بكسل بدقة. JPG يتجاهل التفاصيل الدقيقة التي لا تلاحظها العين.</p>\n<p>للصور الفوتوغرافية، الفرق هائل: PNG قد يكون خمس مرات أكبر من JPG. هذا ثمن حفظ كل بكسل.</p>\n<h2 id=\"when-it-is-useful\">متى يكون JPG إلى PNG مفيدًا فعلًا؟</h2>\n<p>متى يكون JPG إلى PNG مفيدًا فعلًا؟ عندما تحتاج إلى تحرير متكرر دون فقدان إضافي، أو نصوص حادة في مستندات ممسوحة.</p>\n<p>PNG مفيد أيضًا للأرشفة: نسخة رئيسية دون فقدان تحفظ الصورة كما هي. للأرشيف، PNG خيار جيد.</p>\n<h2 id=\"when-it-is-pointless\">متى لا معنى لتحويل JPG إلى PNG؟</h2>\n<p>متى لا معنى لتحويل JPG إلى PNG؟ عندما تريد فقط مشاركة صورة أو رفعها إلى موقع. الملف الأكبر لا يضيف أي جودة.</p>\n<p>للويب، استخدم WebP بدل PNG. وللتحويل إلى WebP، استخدم <a href=\"/ar/tahwil-jpg-ila-webp/\">محول JPG إلى WebP</a>. WebP أصغر بكثير ويحافظ على الجودة.</p>\n<h2 id=\"no-quality-slider\">لماذا لا يوجد منزلق جودة؟</h2>\n<p>لماذا لا يوجد منزلق جودة؟ لأن PNG ضغط دون فقدان: لا توجد جودة قابلة للتعديل. كل بكسل يُحفظ بدقة كاملة.</p>\n<p>غياب المنزلق ليس نقصًا في الأداة. PNG لا يملك إعداد جودة، فالضغط دون فقدان يعني حفظ كل شيء.</p>\n<h2 id=\"transparency-myth\">أسطورة الشفافية</h2>\n<p>أسطورة الشفافية: التحويل من JPG إلى PNG لا يضيف شفافية. JPG لا يحمل معلومات شفافية، والملف المحوّل سيكون له خلفية صلبة.</p>\n<p>إذا أردت صورة شفافة، فابدأ من مصدر شفاف مثل PNG أو WebP. لا يمكن خلق الشفافية من صورة لا تملكها.</p>\n<h2 id=\"renaming-is-not-converting\">تغيير الاسم ليس تحويلًا</h2>\n<p>تغيير الاسم ليس تحويلًا: تغيير امتداد الملف من jpg إلى png لا يغيّر الصيغة. الملف يبقى JPG من الداخل.</p>\n<p>بعض البرامج ترفض الملف أو تعرضه بشكل خاطئ بعد تغيير الاسم. التحويل الحقيقي يعيد ترميز البيانات لا تغيير الاسم.</p>\n<h2 id=\"batch-converting\">كيف تحوّل JPG إلى PNG بالجملة؟</h2>\n<p>لتحويل JPG إلى PNG بالجملة، ارفع كل الملفات وحوّلها بإعدادات موحدة. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP.</p>\n<p>توقع أن يكون ملف ZIP كبيرًا. PNG أكبر من JPG، ودفعة من 20 صورة قد تزن مئات الميغابايت.</p>\n<h2 id=\"cmyk-and-colour\">JPG بنمط CMYK وتغيّرات اللون</h2>\n<p>JPG بنمط CMYK وتغيّرات اللون: بعض ملفات JPG تستخدم نمط ألوان CMYK للطباعة. التحويل إلى PNG قد يغيّر الألوان قليلًا.</p>\n<p>إذا تغيرت الألوان بعد التحويل، فحوّل الملف أولًا إلى RGB ثم إلى PNG. التحويل المباشر من CMYK قد يسبب انحرافًا لونيًا.</p>\n<h2 id=\"editing-workflow\">سير عمل تحرير معقول</h2>\n<p>سير عمل تحرير معقول: حوّل إلى PNG قبل التحرير المكثف، وحرر النسخة PNG، ثم صدّر النتيجة النهائية بصيغة مناسبة.</p>\n<p>بهذا تتجنب فقدان الجودة في كل جولة تحرير. PNG هو صيغة العمل، وJPG أو WebP هما صيغتا التسليم.</p>\n<h2 id=\"exif-and-privacy\">بيانات EXIF والخصوصية</h2>\n<p>بيانات EXIF والخصوصية: ملفات JPG تحمل بيانات EXIF مثل الموقع والتاريخ. التحويل إلى PNG قد يزيل بعض هذه البيانات أو يحافظ عليها.</p>\n<p>تحقق من بيانات الملف المحوّل قبل مشاركته. إذا أردت إزالة بيانات الموقع، فاستخدم أداة إزالة البيانات الوصفية قبل المشاركة.</p>\n<h2 id=\"compatibility\">أين تعمل ملفات PNG بشكل أفضل؟</h2>\n<p>أين تعمل ملفات PNG بشكل أفضل؟ في الرسوم والنصوص والشعارات ولقطات الشاشة. PNG يحفظ الحواف الحادة بوضوح.</p>\n<p>للصور الفوتوغرافية، JPG أو WebP أفضل. PNG مخصص للرسوم لا للصور الفوتوغرافية.</p>\n<h2 id=\"png-for-presentations\">PNG للعروض التقديمية</h2>\n<p>PNG للعروض التقديمية: استخدم PNG للرسوم والشعارات في العروض. الحواف الحادة تبدو نظيفة على الشاشة الكبيرة.</p>\n<p>للصور الفوتوغرافية في العروض، استخدم JPG لتقليل حجم الملف. العرض الكبير لا يحتاج إلى ملفات PNG ضخمة.</p>\n<h2 id=\"png-for-social-graphics\">PNG لرسوم وسائل التواصل</h2>\n<p>PNG لرسوم وسائل التواصل: استخدم PNG للرسوم ذات النصوص والشعارات. النص يبقى حادًا وواضحًا بعد الرفع.</p>\n<p>للصور الفوتوغرافية على وسائل التواصل، استخدم JPG. المنصات تضغط الصور على أي حال، وPNG الكبير لا يضيف شيئًا.</p>\n<h2 id=\"png-for-print-work\">PNG لأعمال الطباعة</h2>\n<p>PNG لأعمال الطباعة: استخدم PNG للرسوم والنصوص التي ستطبعها. الحواف الحادة تطبع بشكل أنظف من JPG.</p>\n<p>للصور الفوتوغرافية المطبوعة، استخدم JPG بجودة عالية. الطباعة تحتاج دقة كاملة، والصيغة أقل أهمية من الدقة.</p>\n<h2 id=\"storing-png-masters\">كيف تحفظ النسخ الرئيسية PNG؟</h2>\n<p>لحفظ النسخ الرئيسية PNG، احتفظ بها في مجلد أرشيف منفصل. النسخة الرئيسية دون فقدان هي مصدر كل نسخة مستقبلية.</p>\n<p>لا تحذف النسخ الرئيسية بعد إنشاء نسخ أصغر. إذا غيّرت المنصة متطلباتها، فستحتاج إلى الأصل.</p>\n<h2 id=\"png-for-app-store-screenshots\">PNG للقطات متجر التطبيقات</h2>\n<p>PNG للقطات متجر التطبيقات: متاجر التطبيقات تطلب لقطات PNG غالبًا. الحواف الحادة والنصوص الواضحة مهمة في لقطات المتجر.</p>\n<p>حوّل لقطاتك إلى PNG باستخدام <a href=\"/ar/tahwil-jpg-ila-png/\">محول JPG إلى PNG</a>. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/kayfiyya-tahwil-jpg-ila-png/\">كيفية تحويل JPG إلى PNG</a> و<a href=\"/ar/blog/jpg-vs-png-al-shafafiyya/\">JPG مقابل PNG والشفافية</a>، أو حوّل إلى WebP باستخدام <a href=\"/ar/tahwil-jpg-ila-webp/\">محول JPG إلى WebP</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل تحويل JPG إلى PNG يجعل صورتي أوضح؟","answer":"لا، التحويل لا يجعل الصورة أوضح. PNG يحفظ JPG كما هو، مع كل عيوبه. الجودة لا تتحسن أبدًا بالتحويل."},{"question":"لماذا أصبح ملف PNG أكبر بخمس مرات من JPG؟","answer":"لأن PNG ضغط دون فقدان: يحفظ كل بكسل بدقة دون تجاهل أي بيانات. JPG يتجاهل التفاصيل الدقيقة، لذلك يكون أصغر بكثير."},{"question":"هل تحويل JPG إلى PNG يضيف شفافية إلى صورة؟","answer":"لا، التحويل لا يضيف شفافية إلى صورة. JPG لا يحمل معلومات شفافية، وPNG المحوّل سيكون له خلفية صلبة مثل الأصل."},{"question":"هل تحويل JPG إلى PNG آمن للمستندات الممسوحة؟","answer":"نعم، التحويل آمن للمستندات الممسوحة. PNG يحفظ النصوص والخطوط بوضوح أكبر من JPG، وهو مناسب للأرشفة."},{"question":"هل يمكنني تحويل JPG إلى PNG على هاتفي؟","answer":"نعم، يعمل التحويل في متصفح هاتفك دون تثبيت أي تطبيق. افتح الأداة وارفع الصورة وحوّلها ونزّل النتيجة."},{"question":"متى أختار JPG إلى PNG بدل JPG إلى WebP؟","answer":"اختر PNG عندما تحتاج إلى تحرير متكرر أو نصوص حادة أو أرشفة دون فقدان. اختر WebP عندما تريد أصغر حجم للويب."}];
